// Generated by `manage.sh scaffold-service` — E2E helpers for ichnos-api.
// Place at E2ETests/tests/ichnos/ichnos-helpers.ts
import type { APIRequestContext, APIResponse } from '@playwright/test';
import { setTimeout as delay } from 'timers/promises';

function resolveIchnosApiUrl(): string {
  const envUrl = process.env.ICHNOS_API_URL;
  if (envUrl && envUrl.trim()) {
    return envUrl.trim().replace(/\/+$/, '');
  }
  return 'http://localhost:5099';
}

export const ICHNOS_API_URL = resolveIchnosApiUrl();

/**
 * Attempt a request against the service; returns null when unreachable so specs
 * can `test.skip` gracefully in environments where the service isn't deployed.
 */
export async function tryRequest(
  request: APIRequestContext,
  path: string,
  options: {
    method?: 'GET' | 'POST' | 'DELETE' | 'PUT';
    data?: unknown;
    headers?: Record<string, string>;
  } = {},
): Promise<{ response: APIResponse; url: string } | null> {
  const url = `${ICHNOS_API_URL}${path}`;
  try {
    const response = await request.fetch(url, {
      method: options.method ?? 'GET',
      data: options.data as never,
      headers: options.headers,
      timeout: 10_000,
    });
    return { response, url };
  } catch {
    return null;
  }
}

/**
 * Acquire an `ichnos`-realm access token via Resource Owner Password Credentials.
 *
 * Returns null (so the caller `test.skip`s the authed assertions) when the
 * Keycloak base / credentials / client aren't configured in the active env —
 * the unauthenticated negative assertions in the spec always run regardless.
 *
 * MUST use a TENANT user (carries a `tenantId` claim), not the platform
 * superUser — screenings are tenant-scoped and reject a tenant-less principal
 * with 401. Credentials come from ICHNOS_TEST_USERNAME / ICHNOS_TEST_PASSWORD
 * (the seeded `ichnos-tenant` user); if unset the authed test skips rather than
 * false-fail on superUser.
 *
 * Client is configurable: defaults to `bff-ichnos-client` (the confidential
 * client whose direct-access-grant path M0 proved end-to-end); the runner
 * supplies its secret via ICHNOS_E2E_CLIENT_SECRET. A public client with DAG
 * can be used by setting ICHNOS_E2E_CLIENT_ID with no secret.
 */
export async function getIchnosToken(): Promise<string | null> {
  const kcBase = resolveKeycloakBaseUrl();
  const username = process.env.ICHNOS_TEST_USERNAME?.trim();
  const password = process.env.ICHNOS_TEST_PASSWORD?.trim();
  if (!kcBase || !username || !password) return null;

  const clientId = process.env.ICHNOS_E2E_CLIENT_ID?.trim() || 'bff-ichnos-client';
  const clientSecret = process.env.ICHNOS_E2E_CLIENT_SECRET?.trim();

  const fields: Record<string, string> = {
    grant_type: 'password',
    client_id: clientId,
    username,
    password,
    scope: 'openid',
  };
  if (clientSecret) fields.client_secret = clientSecret;

  try {
    const res = await fetch(`${kcBase}/realms/ichnos/protocol/openid-connect/token`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams(fields).toString(),
    });
    if (!res.ok) return null;
    const body = (await res.json()) as { access_token?: string };
    return body.access_token ?? null;
  } catch {
    return null;
  }
}

/** Derive the Keycloak base URL (no `/realms/...`) from KEYCLOAK_URL or KEYCLOAK_ISSUER. */
function resolveKeycloakBaseUrl(): string | null {
  const explicit = process.env.KEYCLOAK_URL?.trim();
  if (explicit) return explicit.replace(/\/+$/, '');
  const issuer = process.env.KEYCLOAK_ISSUER?.trim();
  if (!issuer) return null;
  const match = /^(.*?)\/realms\/[^/]+/.exec(issuer);
  return match?.[1] ? match[1].replace(/\/+$/, '') : null;
}

/** Poll a health path until 200 or timeout. */
export async function waitForHealthy(
  request: APIRequestContext,
  path: string,
  timeoutMs = 30_000,
): Promise<{ response: APIResponse; url: string }> {
  const url = `${ICHNOS_API_URL}${path}`;
  const deadline = Date.now() + timeoutMs;
  let last: APIResponse = await request.fetch(url, { timeout: 5_000 });
  while (!last.ok() && Date.now() <= deadline) {
    await delay(1_000);
    last = await request.fetch(url, { timeout: 5_000 });
  }
  return { response: last, url };
}

// ---------------------------------------------------------------------------
// M1-10 two-tier E2E — BFF onboarding (F1), API keys (F3), batch (F4), billing (F7).
// ---------------------------------------------------------------------------

/**
 * The ichnos-web SPA host — same origin as the `bff-ichnos` BFF. `/bff/*` auth
 * endpoints and the `/bff/api/*` proxy both live here. Resolved from
 * ICHNOS_WEB_URL (staging: https://staging.app.ichnos.dloizides.com); when unset
 * the onboarding + portal specs `test.skip` gracefully (dev PC can't reach it).
 */
export function resolveIchnosWebUrl(): string | null {
  const envUrl = process.env.ICHNOS_WEB_URL;
  if (envUrl && envUrl.trim()) return envUrl.trim().replace(/\/+$/, '');
  return null;
}

export const ICHNOS_WEB_URL = resolveIchnosWebUrl();

/** The BFF's anti-forgery contract — every state-changing `/bff/*` call needs this header + an allow-listed Origin. */
export const BFF_CSRF_HEADER = 'X-BFF-Csrf';
export const BFF_CSRF_VALUE = '1';

/** A well-formed, plainly non-sanctioned address — screens as "clear". */
export const CLEAR_BTC_ADDRESS = { chain: 'BTC', address: '1A1zP1eP5QGefi2DMPTfTL5SLmv7DivfNa' };

/** A REAL OFAC-listed TRON address — screens as a DIRECT "direct" hit against OFAC. */
export const SANCTIONED_TRX_ADDRESS = { chain: 'TRX', address: 'TNiq9AXBp9EjUqhDhrwrfvAA8U3GUQZH81' };

/** Shared strong password for the E2E-registered onboarding user. */
export const ICHNOS_E2E_PASSWORD = 'Str0ng!ichnosE2e1';

/**
 * POST a `/bff/*` endpoint with the CSRF header + explicit Origin the BFF
 * requires (Playwright's request context — unlike a browser — does not add
 * Origin). Returns null on a transport error so the caller can `test.skip`.
 * Cookies set by the BFF (the session cookie) persist on the caller's request
 * context, so a register → login → proxied-screen chain shares one session.
 */
export async function bffTryPost(
  request: APIRequestContext,
  webUrl: string,
  path: string,
  data: unknown,
): Promise<APIResponse | null> {
  try {
    return await request.post(`${webUrl}${path}`, {
      headers: { [BFF_CSRF_HEADER]: BFF_CSRF_VALUE, Origin: webUrl, 'Content-Type': 'application/json' },
      data: data as never,
      timeout: 20_000,
    });
  } catch {
    return null;
  }
}

/**
 * Derive a Keycloak-legal username from an email. TenantService's register
 * validator only allows letters, digits, underscore, dot, or dash — so the raw
 * email (with its `@`) 400s. Mirrors ichnos-web's deriveUsername exactly. The
 * user still signs in by email (Keycloak resolves email → user).
 */
const USERNAME_DISALLOWED = /[^a-z0-9._-]+/g;
export function deriveUsername(email: string): string {
  return email.trim().toLowerCase().replace(USERNAME_DISALLOWED, '-');
}

/** A unique email per run (timestamp + random) so each register creates a fresh tenant. */
export function uniqueIchnosEmail(): string {
  const stamp = `${Date.now().toString(36)}${Math.floor(Math.random() * 1_000_000).toString(36)}`;
  return `ichnos-e2e-${stamp}@example.com`;
}

/** A freshly-registered onboarding user + the raw register response. */
export interface RegisteredIchnosUser {
  email: string;
  username: string;
  password: string;
  response: APIResponse;
}

/**
 * Register a FRESH ichnos user via the BFF (`POST /bff/register`). Username is
 * DERIVED from the email (raw email 400s); a unique email per run means a fresh
 * tenant each time. Returns null when the BFF is unreachable.
 */
export async function registerIchnosUser(
  request: APIRequestContext,
  webUrl: string,
): Promise<RegisteredIchnosUser | null> {
  const email = uniqueIchnosEmail();
  const username = deriveUsername(email);
  const response = await bffTryPost(request, webUrl, '/bff/register', {
    firstName: 'Ichnos',
    lastName: 'E2E',
    username,
    email,
    password: ICHNOS_E2E_PASSWORD,
    tenantName: `Ichnos E2E ${username}`,
    verifyUrlTemplate: `${webUrl}/verify-email?token={token}`,
  });
  if (!response) return null;
  return { email, username, password: ICHNOS_E2E_PASSWORD, response };
}

/**
 * Log in via the BFF (`POST /bff/login`). The BFF field is `username`, set to
 * the EMAIL — Keycloak resolves email → user (register needs an @-free username;
 * login does not). Mirrors the shipped bffAuthClient.login call.
 */
export function bffLogin(
  request: APIRequestContext,
  webUrl: string,
  email: string,
  password: string,
): Promise<APIResponse | null> {
  return bffTryPost(request, webUrl, '/bff/login', { username: email, password });
}

/** The plaintext-once result of issuing a customer API key. */
export interface IssueApiKeyResult {
  id: string;
  plaintext: string;
  prefix: string;
  label: string;
  createdAt: string;
}

/**
 * Issue a customer API key (JWT-authed `POST /v1/api-keys`). Returns the parsed
 * result (plaintext returned ONCE) on a 2xx, else null.
 */
export async function issueApiKey(
  request: APIRequestContext,
  token: string,
  label = 'e2e',
): Promise<IssueApiKeyResult | null> {
  const result = await tryRequest(request, '/v1/api-keys', {
    method: 'POST',
    data: { label },
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
  });
  if (!result || result.response.status() >= 300) return null;
  return (await result.response.json()) as IssueApiKeyResult;
}

/**
 * Build a Playwright multipart body for a CSV upload. FastEndpoints binds the
 * `IFormFile File` from a form field named `file` (case-insensitive).
 */
export function csvMultipart(
  csv: string,
  filename = 'batch.csv',
): { file: { name: string; mimeType: string; buffer: Buffer } } {
  return { file: { name: filename, mimeType: 'text/csv', buffer: Buffer.from(csv, 'utf-8') } };
}

// --- M3 Wave-4 — monitoring / alerts / webhooks / regulator packs shared bits ---
/** HTTP 402 — the Growth+ plan gate response emitted by PlanGate.WritePaymentRequiredAsync. */
export const PAYMENT_REQUIRED = 402;

/** Bearer Authorization header (GET/DELETE); jsonAuth adds JSON content-type (POST/PUT). */
export function bearer(token: string): Record<string, string> {
  return { Authorization: `Bearer ${token}` };
}
export function jsonAuth(token: string): Record<string, string> {
  return { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` };
}

/** A PUBLIC https webhook sink the nightly runner can reach (both-channels delivery E2E); unset → skip. */
export const ICHNOS_WEBHOOK_SINK_URL: string | null = (() => {
  const envUrl = process.env.ICHNOS_WEBHOOK_SINK_URL;
  return envUrl && envUrl.trim() ? envUrl.trim().replace(/\/+$/, '') : null;
})();

/** Whether an IMAP inbox is configured to assert a real alert EMAIL (host+user+password). */
export function hasEmailInboxConfigured(): boolean {
  const host = process.env.ICHNOS_IMAP_HOST?.trim() || process.env.IMAP_HOST?.trim();
  const user = process.env.ICHNOS_IMAP_USER?.trim() || process.env.IMAP_USER?.trim();
  const pass = process.env.ICHNOS_IMAP_PASSWORD?.trim() || process.env.IMAP_PASSWORD?.trim();
  return Boolean(host && user && pass);
}
